from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')

start = s.index('function getScheduleDisciplines(){')
end = s.index("\n$('saveScheduleSettings')", start)

replacement = r'''function getScheduleDisciplines(){return db.disciplines.filter(d=>d.active!==false)}
function seededHash(s){let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return Math.abs(h)}
function dateKey(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function buildSchedule(monthOffset=0){const now=new Date(),month=new Date(now.getFullYear(),now.getMonth()+monthOffset,1),year=month.getFullYear(),mo=month.getMonth(),days=[],last=new Date(year,mo+1,0).getDate();for(let i=1;i<=last;i++)days.push(new Date(year,mo,i));const disciplines=getScheduleDisciplines(),perDay=Math.max(1,Number(db.schedule.perDay)||1),totalSlots=days.length*perDay;if(!disciplines.length)return days.map(date=>({date,slots:[]}));const counts=Object.fromEntries(disciplines.map(d=>[d.name,1])),remaining=Math.max(0,totalSlots-disciplines.length),weightSum=disciplines.reduce((a,d)=>a+(Number(d.weight)||1),0),extras=Object.fromEntries(disciplines.map(d=>[d.name,Math.floor(remaining*(Number(d.weight)||1)/weightSum)]));let used=disciplines.reduce((a,d)=>a+extras[d.name],0),rem=remaining-used;disciplines.slice().sort((a,b)=>seededHash(a.name)-seededHash(b.name)).forEach(d=>{if(rem>0){extras[d.name]++;rem--}});disciplines.forEach(d=>counts[d.name]+=extras[d.name]);const remainingCount={...counts},result=[];let idx=0;for(const date of days){const slots=[],usedNames=new Set();for(let n=0;n<perDay;n++){let candidates=disciplines.filter(d=>remainingCount[d.name]>0&&!usedNames.has(d.name)).sort((a,b)=>remainingCount[b.name]-remainingCount[a.name]||seededHash(a.name+dateKey(date)+idx)-seededHash(b.name+dateKey(date)+idx));if(!candidates.length)candidates=disciplines.filter(d=>remainingCount[d.name]>0);if(!candidates.length)break;const d=candidates[0];remainingCount[d.name]--;usedNames.add(d.name);slots.push(d)}result.push({date,slots});idx++}return result}
function buildWeekSchedule(){const base=new Date();base.setHours(0,0,0,0);const sunday=new Date(base);sunday.setDate(base.getDate()-base.getDay());return Array.from({length:7},(_,i)=>{const date=new Date(sunday);date.setDate(sunday.getDate()+i);const offset=(date.getFullYear()-base.getFullYear())*12+date.getMonth()-base.getMonth();const item=buildSchedule(offset).find(x=>dateKey(x.date)===dateKey(date));return item||{date,slots:[]}})}
function renderSchedule(){const perDay=Math.max(1,Number(db.schedule.perDay)||1),week=buildWeekSchedule(),month=buildSchedule(0),dow=['DOM','SEG','TER','QUA','QUI','SEX','SÁB'];const ws=week[0]?.date||new Date(),we=week[6]?.date||ws;const header=`<div class="calendar-month-bar"><div class="calendar-month-title">Semana atual</div><div class="calendar-month-range">${fmtDate(dateKey(ws))} → ${fmtDate(dateKey(we))}</div></div><div class="calendar-head-row">${dow.map((x,i)=>`<div class="calendar-week-header ${i===0||i===6?'weekend':''}"><span>${x}</span><small>${String(week[i].date.getDate()).padStart(2,'0')}</small></div>`).join('')}</div>`;const weekCells=week.map(item=>{const k=dateKey(item.date),isToday=k===today;return `<div class="calendar-cell ${item.date.getDay()===0||item.date.getDay()===6?'weekend':''} ${isToday?'today':''}"><div class="calendar-date"><strong>${item.date.getDate()}</strong><span>${dow[item.date.getDay()]}</span>${isToday?'<b>HOJE</b>':''}</div><div class="calendar-cell-content">${item.slots.length?item.slots.map(d=>{const key=`${k}|${d.name}`,completed=!!db.schedule.completed[key];return `<div class="calendar-study ${completed?'done':''}" style="--subject-color:${d.color||'#00e5ff'}"><div class="calendar-study-status">${completed?'CONCLUÍDO':'ESTUDO'}</div><div class="calendar-study-title">${esc(d.name)}</div><div class="calendar-study-time">${fmtMin(Math.max(1,Math.round((Number(db.schedule.hours)||10)*60/(7*perDay))))}</div><div class="calendar-study-meta"><span>${esc(d.name)}</span></div><button type="button" class="calendar-study-action ${completed?'done-action':''}" onclick="toggleScheduleDay('${k}','${encodeURIComponent(d.name)}')">${completed?'✓ Estudado':'Marcar como estudado'}</button></div>`}).join(''):'<div class="calendar-free">—</div>'}</div></div>`}).join('');$('weeklySchedule').innerHTML=`<div class="study-calendar">${header}<div class="calendar-grid-row">${weekCells}</div></div>`;const monthStart=month[0]?.date||new Date(),first=monthStart.getDay(),monthCells=[];for(let i=0;i<first;i++)monthCells.push('<div class="month-cell outside"></div>');month.forEach(item=>{const k=dateKey(item.date),isToday=k===today;monthCells.push(`<div class="month-cell ${item.date.getDay()===0||item.date.getDay()===6?'weekend':''} ${isToday?'today':''}"><div class="month-date"><strong>${item.date.getDate()}</strong>${isToday?'<span class="month-today">HOJE</span>':''}</div>${item.slots.map(d=>{const key=`${k}|${d.name}`,done=!!db.schedule.completed[key];return `<div class="month-study ${done?'done':''}" style="--subject-color:${d.color||'#00e5ff'}"><div class="month-study-name">${esc(d.name)}</div><div class="month-study-info">${done?'Concluído':'Planejado'}</div><button type="button" class="calendar-study-action ${done?'done-action':''}" onclick="toggleScheduleDay('${k}','${encodeURIComponent(d.name)}')">${done?'✓ Estudado':'Marcar'}</button></div>`}).join('')||'<div class="month-empty">—</div>'}</div>`)});while(monthCells.length%7)monthCells.push('<div class="month-cell outside"></div>');const monthName=monthStart.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});$('monthlySchedule').innerHTML=`<div class="month-calendar"><div class="calendar-month-bar"><div class="calendar-month-title">${monthName}</div><div class="calendar-month-range">${fmtDate(dateKey(monthStart))} → ${fmtDate(dateKey(month[month.length-1]?.date||monthStart))}</div></div><div class="month-head-row">${dow.map(x=>`<div class="month-head">${x}</div>`).join('')}</div><div class="month-grid">${monthCells.join('')}</div></div>`;$('cronogramaModePill').textContent=`${perDay} disciplina${perDay>1?'s':''}/dia`}
function toggleScheduleDay(date,nameEncoded){const name=decodeURIComponent(nameEncoded),key=`${date}|${name}`;db.schedule=db.schedule||{hours:10,perDay:1,completed:{}};db.schedule.completed=db.schedule.completed||{};db.schedule.completed[key]=!db.schedule.completed[key];persist(db.schedule.completed[key]?'Dia marcado como estudado.':'Marcação removida.')}
'''

p.write_text(s[:start] + replacement + s[end:], encoding='utf-8')
print('cronograma repaired')